window.LP.BookData[5] = {"n": 5, "title": "Симплекс арга", "route": "simplex", "blocks": [{"t": "p", "x": "Өмнөх бүлгүүдэд бид шугаман программчлалын бодлогыг бодлогын тавилт (Бүлэг 2), графикийн арга (Бүлэг 3), матрицын арга (Бүлэг 4) гэсэн гурван өнцгөөс харлаа. Гурван арга бүгд нэг зорилготой байсан: “Модон урлал” ХХК хэдэн ширээ, хэдэн сандал үйлдвэрлэвэл ашиг хамгийн их болох вэ гэдгийг олох. Гурвуулаа ижил хариу — 20 ширээ, 10 сандал, 1,400,000₮ ашиг — өгсөн."}, {"t": "p", "x": "Гэвч эдгээр хоёр аргын (график, матриц) аль алинд нь томоохон сул тал бий. Графикийн арга зөвхөн хоёр хувьсагчтай үед ажилладаг — 3, 4, 5 хувьсагч болмогц зурах хавтгайгаа алддаг. Матрицын арга бүх хязгаарлалтыг яг тэнцүү (=) байхыг шаарддаг бол бодит бизнесийн хязгаарлалт ихэвчлэн тэнцэтгэл биш (≤) хэлбэртэй байдаг."}, {"t": "p", "x": "Энэ бүлэгт бид эдгээр сул талыг арилгасан, орчин үеийн бүх LP шийдвэрлэгч программ хангамжийн (Excel Solver, LINGO, CPLEX) үндэс болсон симплекс аргатай танилцана. Энэ бол сурах бичгийн хамгийн чухал бүлэг: Бүлэг 6 (Big-M арга), Бүлэг 7 (хосмог бодлого) хоёулаа энэ бүлэгт эзэмшсэн мэдлэг дээр суурилна."}, {"t": "h", "lvl": 2, "x": "5.1. Симплекс аргын танилцуулга"}, {"t": "h", "lvl": 3, "x": "5.1.1. Симплекс арга гэж юу вэ?"}, {"t": "p", "x": "Симплекс арга (Simplex Method) нь америкийн математикч Ж.Б. Данцигийн (George B. Dantzig) 1947 онд бүтээсэн алгоритм бөгөөд шугаман программчлалын бодлогыг шийдвэрлэх хамгийн чухал, хамгийн өргөн хэрэглэгддэг арга юм. Бүлэг 1-т өгүүлсэнчлэн, энэхүү алгоритмыг Дэлхийн 2-р дайны үеийн ложистикийн хүнд асуудлуудыг шийдвэрлэх зорилгоор боловсруулсан бөгөөд дараа нь компьютерийн хөгжилтэй хамт бизнес, засгийн газар, инженерчлэлийн салбарт өргөн нэвтэрсэн."}, {"t": "p", "x": "Өнөөдөр хэрэглэгдэж буй бараг бүх LP шийдвэрлэгч программ хангамж — Excel-ийн Solver, LINGO, CPLEX, Gurobi зэрэг — симплекс аргыг, эсвэл түүний сайжруулсан хувилбаруудыг дотроо ашигладаг. Иймд симплекс аргыг эзэмшинэ гэдэг нь зөвхөн гараар бодлого бодох чадвар олгохоос гадна, эдгээр программ хангамж дотроо юу хийж байгааг ойлгох түлхүүр болдог."}, {"t": "h", "lvl": 3, "x": "5.1.2. Хэзээ ашиглах вэ?"}, {"t": "p", "x": "Гурав ба түүнээс дээш хувьсагчтай бодлогод — графикийн арга (Бүлэг 3) хоёр хэмжээст хавтгайгаас цааш ажилладаггүй."}, {"t": "p", "x": "Бүх хязгаарлалт нь ≤ (бага буюу тэнцүү) тэмдэгтэй, max зорилготой бодлогод — энэ бол симплекс аргын стандарт тохиолдол."}, {"t": "p", "x": "Хязгаарлалтын систем тэнцэтгэл биш (≤) агуулж байгаа тул матрицын арга (Бүлэг 4, зөвхөн AX = B тэгшитгэлийн систем дээр ажилладаг) шууд хэрэглэгдэхгүй үед."}, {"t": "p", "x": "Олон мянган хувьсагч, олон зуун хязгаарлалттай бодит бизнесийн бодлогод — энд симплекс арга бол компьютерийн тооцоололд тохирсон цорын ганц бодит боломж юм."}, {"t": "h", "lvl": 3, "x": "5.1.3. Симплекс аргын үндсэн санаа"}, {"t": "p", "x": "Бүлэг 3.3-т үзсэн оройн цэгийн онолыг эргэн санацгаая: шугаман программчлалын бодлогын оновчтой шийд үргэлж боломжит мужийн оройн цэг (Corner Point) дээр байрладаг. Графикийн аргаар бид эдгээр оройн цэгийг нүдээр харж, харьцуулж чадсан. Гэвч 3, 4, 5 хэмжээст орон зайд оройн цэгүүд хэдэн зуугаар тоологдож болох тул тэдгээрийг бүгдийг нь тооцоолж харьцуулах нь практикт боломжгүй."}, {"t": "p", "x": "Симплекс арга энэ асуудлыг ухаалгаар шийддэг: бүх оройн цэгийг тооцоолохын оронд нэг оройн цэгээс эхэлж, зорилгын функцийг сайжруулах чиглэл рүү, хөрш оройн цэг рүү шилждэг. Энэ нь санамсаргүй тэнэмэл хайлт биш — алгоритм алхам бүрдээ “аль чиглэлд шилжвэл ашиг хамгийн ихээр өсөх вэ?” гэдгийг тооцоолж, зөвхөн тэр чиглэлд шилждэг. Оновчтой оройн цэгт хүрэх хүртэл энэ үйл явц давтагдана."}, {"t": "h", "lvl": 3, "x": "5.1.4. Графикийн аргатай уялдах нь"}, {"t": "p", "x": "Бүлэг 3.3-т үзсэн оройн цэгийн теорем нь симплекс аргын онолын үндэс юм. Симплекс арга бол үнэн хэрэгтээ оройн цэгүүдийг ухаалгаар, зорилготойгоор туулах процесс. Графикийн аргаар бид бүх оройн цэгийг нүдээр харж, аль нь хамгийн сайн болохыг харьцуулж байсан бол, симплекс арга нь үүнийг алгебрын аргаар, компьютерт зориулан автоматжуулсан хувилбар юм."}, {"t": "p", "x": "“Санамсаргүй биш, зорилготой хайлт” — симплекс аргын гол мөн чанарыг ийнхүү нэг өгүүлбэрт багтаан хэлж болно. Алгоритм алхам бүрдээ хамгийн богино замаар оновчтой шийд рүү ойртдог."}, {"t": "h", "lvl": 2, "x": "5.2. Каноник хэлбэрт оруулах"}, {"t": "p", "x": "Симплекс алгоритмыг ажиллуулахын өмнө бид бодлогыг каноник (стандарт) хэлбэрт оруулах шаардлагатай. Энэ бол симплекс аргын анхны бөгөөд чухал алхам юм."}, {"t": "h", "lvl": 3, "x": "5.2.1. Каноник хэлбэр гэж юу вэ?"}, {"t": "p", "x": "Бодлогыг симплекс аргаар бодоход бэлтгэхийн тулд дараах дөрвөн нөхцөлийг хангасан байх ёстой:"}, {"t": "p", "x": "Зорилгын функц нь max байна (хэрэв анх min байсан бол max болгож хувиргана)."}, {"t": "p", "x": "Бүх хязгаарлалт эхэндээ ≤ тэмдэгтэй байна."}, {"t": "p", "x": "Эдгээр ≤ хязгаарлалтыг нэмэлт хувьсагч ашиглан тэгшитгэл (=) болгосон байна."}, {"t": "p", "x": "Бүх хувьсагч — шийдвэрийн хувьсагч ба нэмэлт хувьсагч аль аль нь — x ≥ 0 нөхцөлийг хангана."}, {"t": "p", "x": "Эдгээр дөрвөн шаардлагыг 5.2.4-т үзэх жишээгээр тодорхой харуулна."}, {"t": "h", "lvl": 3, "x": "5.2.2. Нэмэлт хувьсагч (Slack Variable, +S) гэж юу вэ?"}, {"t": "p", "x": "Нэмэлт хувьсагч (Slack Variable) гэдэг нь ≤ тэмдгийг = болгохын тулд тэнцэтгэл бишийн зүүн талд нэмж оруулдаг, үл сөрөг (≥ 0) хувьсагч юм. Жишээ нь:"}, {"t": "p", "x": "4x₁ + 2x₂ ≤ 100  →  4x₁ + 2x₂ + s₁ = 100,  s₁ ≥ 0"}, {"t": "p", "x": "Энд s₁ нь ашиглагдаагүй үлдсэн нөөцийг илэрхийлнэ. Тэнцэтгэл биш байсан хязгаарлалтыг тэгшитгэл болгож чадвал бид түүнийг матрицын арга (Бүлэг 4)-тай адил AX = B хэлбэрт оруулж чадна — ялгаа нь зөвхөн хувьсагчийн тоо нэмэгдсэнд оршино."}, {"t": "h", "lvl": 3, "x": "5.2.3. Нэмэлт хувьсагчийн эдийн засгийн утга"}, {"t": "p", "x": "Нэмэлт хувьсагч зөвхөн математикийн хэрэгсэл биш — тодорхой эдийн засгийн утгатай. “Модон урлал” ХХК-ийн жишээгээр:"}, {"t": "p", "x": "s₁ = ашиглагдаагүй үлдсэн мод (м³)"}, {"t": "p", "x": "s₂ = ажилчдын сул зогссон цаг"}, {"t": "p", "x": "Хэрэв үйлдвэр нөөцөө бүрэн ашиглавал (жишээ нь бүх модыг зарцуулбал) s₁ = 0 болно. Харин үлдэгдэлтэй бол sᵢ > 0. Энэ ялгаа менежментийн шийдвэрт шууд ач холбогдолтой: аль нөөц бүрэн шавхагдаж, аль нь илүүдэлтэй байгааг симплекс хүснэгт шууд харуулдаг."}, {"t": "h", "lvl": 3, "x": "5.2.4. Модон урлалын каноник хэлбэр"}, {"t": "p", "x": "Бүлэг 2.7-т тавьсан “Модон урлал” ХХК-ийн бодлогыг эргэн санацгаая:"}, {"t": "p", "x": "max Z = 50,000x₁ + 40,000x₂\n4x₁ + 2x₂ ≤ 100    (мод)\n2x₁ + 4x₂ ≤ 80    (цаг)\nx₁, x₂ ≥ 0"}, {"t": "p", "x": "Үүнийг каноник хэлбэрт оруулбал:"}, {"t": "p", "x": "max Z = 50,000x₁ + 40,000x₂ + 0·s₁ + 0·s₂\n4x₁ + 2x₂ + s₁ = 100\n2x₁ + 4x₂ + s₂ = 80\nx₁, x₂, s₁, s₂ ≥ 0"}, {"t": "p", "x": "Нэмэлт хувьсагчийн зорилгын функц дэх коэффициент яагаад 0 болохыг анзаараарай: ашиглагдаагүй мод, цаг өөрөө ашиг үүсгэдэггүй, зөвхөн нөөцийн үлдэгдлийг бүртгэж байгаа юм."}, {"t": "h", "lvl": 3, "x": "5.2.5. Каноник хэлбэр ба алгебр"}, {"t": "p", "x": "Каноник хэлбэрт оруулах үйлдэл нь цаанаа ямар нэгэн гүн философи биш — тэнцэтгэл бишийг тэгшитгэл болгосон энгийн алгебрын шилжүүлэлт юм. Үүний үр дүнд хувьсагчийн тоо нэмэгдсэн (2 → 4), харин хязгаарлалтын тоо өөрчлөгдөөгүй хэвээр байна. Ингэснээр бид математикийн хувьд тэгш хэлбэртэй тэгшитгэлийн систем олж авах бөгөөд яг үүн дээр симплекс алгоритм ажиллана."}, {"t": "p", "x": "→ ≥ болон = тэмдэгтэй хязгаарлалтад зориулсан каноник хэлбэрийн алгебрыг (илүүдэл ба зохиомол хувьсагч ашиглан) Бүлэг 6.2-т дэлгэрүүлж үзнэ."}, {"t": "h", "lvl": 2, "x": "5.3. Анхны симплекс хүснэгт байгуулах"}, {"t": "h", "lvl": 3, "x": "5.3.1. Симплекс хүснэгт гэж юу вэ?"}, {"t": "p", "x": "Симплекс хүснэгт (Simplex Tableau) нь симплекс алгоритмыг ажиллуулах гол хэрэглүүр юм. Энэ хүснэгт бодлогын бүх мэдээллийг — коэффициент, хязгаарлалт, зорилгын функцийг — нэг дор хураангуйлан харуулдаг бөгөөд алгоритмын үе шат (iteration) бүрд шинэчлэгддэг."}, {"t": "h", "lvl": 3, "x": "5.3.2. Хүснэгтийн бүтэц"}, {"t": "p", "x": "“Модон урлал” ХХК-ийн каноник хэлбэрийг (5.2.4-т үзсэнчлэн) симплекс хүснэгтэд шилжүүлбэл:"}, {"t": "table", "rows": [["Суурь", "x₁ (Ширээ)", "x₂ (Сандал)", "s₁ (Мод)", "s₂ (Цаг)", "RHS"], ["s₁", "4", "2", "1", "0", "100"], ["s₂", "2", "4", "0", "1", "80"], ["Z", "−50", "−40", "0", "0", "0"]]}, {"t": "p", "x": "Хүснэгтийн бүрэлдэхүүн хэсгүүд:"}, {"t": "p", "x": "Суурь (Basis) багана: одоогийн суурь хувьсагчид. Эхэндээ эдгээр нь s₁, s₂ — учир нь яг эдгээр хувьсагч тэгшитгэл бүрт ганцаараа зогсож байна."}, {"t": "p", "x": "x₁, x₂: шийдвэрийн хувьсагчид."}, {"t": "p", "x": "s₁, s₂: нэмэлт хувьсагчид."}, {"t": "p", "x": "RHS (Right Hand Side): тэгшитгэл бүрийн сул гишүүн буюу одоогийн хязгаарлалтын хэмжээ."}, {"t": "p", "x": "Z мөр: зорилгын функцийг илэрхийлэх тусгай мөр."}, {"t": "h", "lvl": 3, "x": "5.3.3. Z мөрийн бүтэц — яагаад −50, −40 вэ?"}, {"t": "p", "x": "Онцгой чухал хэсэг. Симплекс хүснэгтийг анх харсан оюутнууд ихэвчлэн “Ашгаа хамгийн их байлгах зорилготой атлаа яагаад гэнэт хасах тэмдэгтэй (−50, −40) тоо гарч ирээд, бас 0-тэй тэнцүүлчихэв ээ?” гэж гайхдаг. Үүнийг математикийн болон симплекс алгоритмын гэсэн хоёр талаас нь тайлбарлая."}, {"t": "p", "x": "1. Математик (алгебр)-ийн шалтгаан. Энэ бол ердөө тэгшитгэлийн нэг талаас нөгөө тал руу шилжүүлж буй энгийн үйлдэл. Зорилгын функц Z = 50000x₁ + 40000x₂-ийг стандарт хэлбэрт оруулахын тулд симплекс арга бүх хувьсагчийг тэнцүүгийн зүүн талд, харин сул гишүүнийг баруун талд байлгахыг шаарддаг:"}, {"t": "p", "x": "Анхны хэлбэр: Z = 50000x₁ + 40000x₂\nШилжүүлэх: Z − 50000x₁ − 40000x₂ = 0"}, {"t": "p", "x": "Математикийн дүрмээр нэмэх тэмдэгтэй байсан тоо тэнцүүгийн тэмдгийн нөгөө тал руу шилжихдээ хасах болж хувирдаг. Тиймээс симплекс хүснэгтийн хамгийн доод талын Z мөрөнд бичигдэх тоонууд −50000, −40000 (үүнийг 1000-аар багасгаад −50, −40) болж орж ирдэг."}, {"t": "p", "x": "2. Симплекс алгоритмын шалтгаан (эдийн засгийн логик). Симплекс алгоритм анх хүснэгт байгуулахдаа үргэлж “одоогийн ашиг = 0”, өөрөөр хэлбэл ямар ч бүтээгдэхүүн үйлдвэрлээгүй гэсэн гарааны цэгээс эхэлдэг. Доод мөрөнд байгаа −50 гэсэн тоог алгоритм ингэж уншина: “Хэрэв би нэг ширхэг ширээ (x₁) хийхгүй бол олох байсан 50,000₮-ийн ашиг маань алдагдаж байна.” Тиймээс алгоритм эдгээр хасах тоог, өөрөөр хэлбэл ашиглаагүй боломжийг арилгахын тулд аль болох хурдан үйлдвэрлэл эхлүүлэх хэрэгтэй гэж “ойлгоод”, хамгийн их хасах тоотой буюу хамгийн их ашиг өгөх баганыг сонгож бодолтоо эхэлдэг."}, {"t": "p", "x": "Практикт: сөрөг тэмдэг нь боломжийг илэрхийлнэ; хамгийн сөрөг тоо нь хамгийн их боломжийг заана. Симплекс арга эдгээр хасах тоо бүгд арилж дуустал алхам алхмаар үйлдвэрлэлээ өргөтгөсөөр байх бөгөөд Z мөрөнд хасах тоо үлдээгүй нь “цаашид ашиг өсөх боломжгүй, оновчтой (max) цэгтээ хүрлээ” гэсэн дохио болдог."}, {"t": "h", "lvl": 3, "x": "5.3.4. Матрицын аргын симплекстэй уялдаа"}, {"t": "p", "x": "Бүлэг 4-т үзсэн матрицын үйлдлүүд симплекс хүснэгтийн ард нуугдаж байгааг анзаарах нь чухал. Симплекс хүснэгт өөрөө нэг төрлийн матриц хэлбэр бөгөөд дараагийн хэсэгт (5.4) үзэх “мөрийн үйлдэл” гэдэг нь үнэндээ матрицын мөр дээрх шугаман хувиргалт юм. Гаусс–Жорданы арга (мөрийг тоогоор үржүүлж, нэмэх буюу хасах) нь Бүлэг 4-т үзсэн урвуу матриц олох аргатай ижил логик дээр суурилдаг — симплекс алгоритм бол энэ логикийг алхам алхмаар, зорилготойгоор ашигладаг хэрэгсэл юм."}, {"t": "h", "lvl": 2, "x": "5.4. Оновчлолын үе шат (Iteration)"}, {"t": "p", "x": "Симплекс алгоритмын нэг оновчлолын үе шат (Iteration) гэдэг нь нэг оройн цэгээс дараагийн, илүү сайн оройн цэг рүү шилжих алхам юм."}, {"t": "h", "lvl": 3, "x": "5.4.1. Оновчлолын үе шатны утга"}, {"t": "p", "x": "Математик утгаар: мөрийн үйлдэл (row operation) хийж хүснэгтийг шинэчлэх."}, {"t": "p", "x": "Менежментийн утгаар: нэг үйлдвэрлэлийн төлөвлөгөөнөөс дараагийн, илүү сайн төлөвлөгөө рүү шилжих."}, {"t": "p", "x": "Геометрийн утгаар: боломжит мужийн нэг оройноос дараагийн оройд шилжих."}, {"t": "p", "x": "Итераци гэдэг үгийг шатрын тоглоомтой зүйрлэж болно: та нэг нүүдэл хийгээд, дараа нь нөхцөл байдлаа харж байгаад илүү сайн дараагийн нүүдлээ хийдэг. Нүүдэл бүр бол нэг итераци. Бид хамгийн сүүлчийн, мад тавих нүүдэл хүртэл итераци хийсээр байдаг."}, {"t": "h", "lvl": 3, "x": "5.4.2. Үе шат бүрд юу хийх вэ?"}, {"t": "p", "x": "(1) Орох баганыг сонгох — шинэ суурь хувьсагчийг тодорхойлно."}, {"t": "p", "x": "(2) Гарах мөрийг сонгох — суурьтайгаа салах хуучин хувьсагчийг тодорхойлно."}, {"t": "p", "x": "(3) Ялгагч элементийг тодорхойлох — орох багана ба гарах мөрийн огтлолцол."}, {"t": "p", "x": "(4) Мөрийн үйлдэл хийж хүснэгтийг шинэчлэх."}, {"t": "p", "x": "(5) Оновчтой эсэхийг шалгах — Z мөрөнд сөрөг тоо байна уу?"}, {"t": "h", "lvl": 3, "x": "5.4.3. Орох багана сонгох (Pivot Column)"}, {"t": "p", "x": "Дүрэм: Z мөрөнд байгаа сөрөг тоонуудаас хамгийн багыг нь агуулсан баганыг сонгоно."}, {"t": "p", "x": "“Модон урлал”-ын жишээгээр Z мөрөнд −50, −40 гэсэн хоёр сөрөг тоо байна. −50 нь −40-өөс жижиг (илүү сөрөг) тул x₁ (ширээ) багана орох багана болно."}, {"t": "p", "x": "Эдийн засгийн утга: ширээ (50 мянган ₮-ийн ашигтай) нь сандлаас (40 мянган ₮) илүү ашигтай тул компани эхлээд дан ширээ хийхээр шийдэж байна. Хэрэв буруу багана сонговол бага ашигтай барааг түрүүлж үйлдвэрлээд, оновчтой шийд рүү очих замаа уртасгана."}, {"t": "h", "lvl": 3, "x": "5.4.4. Гарах мөр сонгох (Pivot Row)"}, {"t": "p", "x": "Дүрэм: RHS-ийг сонгосон баганын эерэг тоонуудад хувааж, гарсан харьцаанаас хамгийн багыг нь сонгоно. Энэ дүрмийг хамгийн бага харьцааны тест (Minimum Ratio Test) гэнэ."}, {"t": "p", "x": "“Модон урлал”-ын жишээгээр:"}, {"t": "p", "x": "s₁ (мод) мөр: 100 / 4 = 25 (хамгийн бага)"}, {"t": "p", "x": "s₂ (цаг) мөр: 80 / 2 = 40"}, {"t": "p", "x": "25 < 40 тул s₁ мөр гарах мөр болно."}, {"t": "p", "x": "Эдийн засгийн утга: хэрэв бид зөвхөн ширээ хийвэл мод ердөө 25 ширээ хийхэд хүрнэ, харин цаг 40 ширээ хийхэд хүрэлцэнэ. Биднийг хамгийн түрүүнд зогсоох зүйл бол мод — энэ бол хамгийн хатуу хязгаарлагч нөөц. Хэрэв бид 40 гэдгийг сонговол үйлдвэрт байхгүй мод хэрэглэж ширээ хийхийг оролдож байна гэсэн үг: хувьсагч сөрөг болж, математикийн хувьд боломжгүй шийд гарна."}, {"t": "h", "lvl": 3, "x": "5.4.5. Ялгагч элемент (Pivot Element) — гол цөм"}, {"t": "p", "x": "Ялгагч элемент бол симплекс аргын гол цөм юм. Үүнийг сайн ойлговол симплекс аргын мөн чанарыг бүрэн ойлгосон хэрэг."}, {"t": "p", "x": "Тодорхойлолт: ялгагч элемент гэдэг нь орох багана ба гарах мөрийн огтлолцол дээрх тоо. “Модон урлал”-ын жишээнд x₁ багана, s₁ мөрийн огтлолцол дээрх 4 гэсэн тоо — энэ бол ялгагч элемент."}, {"t": "p", "x": "Үүрэг: ялгагч элемент дараагийн үе шатанд гол мөрийг нэгж болгож (1 болгож), бусад бүх мөрийн тухайн баганад 0 үлдэхийг баталгаажуулна. Ингэж шинэ суурь хувьсагч цэвэр, ганцаарчилсан хэлбэрт ордог."}, {"t": "h", "lvl": 3, "x": "Ялгагч элементийг хэрхэн ашиглах вэ?"}, {"t": "p", "x": "(1) Гол мөрийг ялгагч элементэд хуваана:"}, {"t": "p", "x": "s₁ мөр ÷ 4:  [4, 2, 1, 0, 100] ÷ 4 = [1, 0.5, 0.25, 0, 25]\n→ Энэ нь дараагийн үе шатанд x₁ мөр болно."}, {"t": "p", "x": "(2) Бусад мөрийг цэвэрлэж, ялгагч баганад 0 үлдээнэ:"}, {"t": "p", "x": "s₂ мөр − 2·(шинэ x₁ мөр):\n[2, 4, 0, 1, 80] − 2·[1, 0.5, 0.25, 0, 25] = [0, 3, −0.5, 1, 30]\n\nZ мөр + 50·(шинэ x₁ мөр):\n[−50, −40, 0, 0, 0] + 50·[1, 0.5, 0.25, 0, 25] = [0, −15, 12.5, 0, 1250]"}, {"t": "p", "x": "Ялгагч элементийн эдийн засгийн утга нь “нэг нэгжийн технологи” рүү шилжих явдал юм. Анхны хязгаарлалт болох 4x₁ + 2x₂ + s₁ = 100 дахь 4 гэсэн тоо нь “1 ширхэг ширээ хийхэд 4 нэгж мод орно” гэсэн технологийн коэффициент. Бид энэ 4-ийг 1 болгож байгаа нь тухайн мөрийн бүх утгыг 4-т хуваан, нэгж бүтээгдэхүүнд ногдох нөөцийн харьцааг тооцож байна гэсэн үг. Ингэснээр бид “4 нэгж мод” гэж ярихаа больж, “1 ширхэг ширээ” гэж шууд ярьж эхэлдэг — анхаарлаа нөөцөөс бүтээгдэхүүн рүү шилжүүлж байгаа хэрэг."}, {"t": "p", "x": "Зүйрлэвэл: “4 ширхэг талх 10,000 төгрөг” гэж ярихаас илүү “1 ширхэг талх 2,500 төгрөг” гэж ярих нь тооцоо хийхэд (жишээ нь 10 талх авахад) хамаагүй хялбар байдагтай ижил логик юм."}, {"t": "p", "x": "Бусад мөрийг 0 болгох нь мөн адил эдийн засгийн утгатай. Цагийн мөр дэх 2-ыг 0 болгох нь “25 ширээ хийхэд зарцуулагдах цагийг цагийн нөөцөөс хасаж, үлдэгдлийг тооцох” буюу нөөцийн дахин хуваарилалтын үйлдэл юм. Ашгийн мөр (Z) дэх −50-ийг 0 болгох нь “ширээний нэгж бүрээс олох 50,000₮-ийн ашгийг нийт ашиг руу (Z = 1250) шилжүүлж, тухайн боломжийг аль хэдийн ашигласныг тэмдэглэх” үйлдэл. Ингэснээр алгоритм “ширээнээс нэмж ашиг олох боломж шавхагдлаа, өөр зүйлээс (сандлаас) ашиг нэмж олох боломж байна уу?” гэдгийг цааш шалгах боломжтой болно."}, {"t": "h", "lvl": 3, "x": "5.4.6. Модон урлалын 1-р оновчлолын үе шат"}, {"t": "p", "x": "Дээрх бүх тооцооллын үр дүнд гарах шинэ хүснэгт:"}, {"t": "table", "rows": [["Суурь", "x₁ (Ширээ)", "x₂ (Сандал)", "s₁ (Мод)", "s₂ (Цаг)", "RHS"], ["x₁", "1", "0.5", "0.25", "0", "25"], ["s₂", "0", "3", "−0.5", "1", "30"], ["Z", "0", "−15", "12.5", "0", "1250"]]}, {"t": "p", "x": "Одоогийн шийд: x₁ = 25, x₂ = 0, Z = 1250 (мянган төгрөгөөр, өөрөөр хэлбэл 1,250,000₮)."}, {"t": "p", "x": "Оновчтой юу? Z мөрөнд сөрөг тоо (x₂ баганад −15) байсаар байна. Тиймээс оновчлол үргэлжилнэ."}, {"t": "h", "lvl": 2, "x": "5.5. Модон урлалын бүрэн симплекс шийдэл"}, {"t": "p", "x": "Бүлэг 2.7-т тавилтыг нь хийж, Бүлэг 3.5-т графикаар, Бүлэг 4.6-т матрицаар шийдсэн бодлогыг эндээс цааш симплекс аргаар бодъё."}, {"t": "h", "lvl": 3, "x": "5.5.1. Бодлогын сануулга"}, {"t": "p", "x": "5.2.4-т каноник хэлбэрт оруулсан загвар:"}, {"t": "p", "x": "max Z = 50,000x₁ + 40,000x₂\n4x₁ + 2x₂ + s₁ = 100\n2x₁ + 4x₂ + s₂ = 80\nx₁, x₂, s₁, s₂ ≥ 0"}, {"t": "h", "lvl": 3, "x": "5.5.2. Анхны симплекс хүснэгт"}, {"t": "p", "x": "(5.3.2-т үзсэнчлэн)"}, {"t": "table", "rows": [["Суурь", "x₁", "x₂", "s₁", "s₂", "RHS"], ["s₁", "4", "2", "1", "0", "100"], ["s₂", "2", "4", "0", "1", "80"], ["Z", "−50", "−40", "0", "0", "0"]]}, {"t": "h", "lvl": 3, "x": "5.5.3. 1-р оновчлолын үе шат"}, {"t": "p", "x": "(5.4.6-т дэлгэрэнгүй үзсэнчлэн: орох багана x₁, гарах мөр s₁, ялгагч элемент 4)"}, {"t": "table", "rows": [["Суурь", "x₁", "x₂", "s₁", "s₂", "RHS"], ["x₁", "1", "0.5", "0.25", "0", "25"], ["s₂", "0", "3", "−0.5", "1", "30"], ["Z", "0", "−15", "12.5", "0", "1250"]]}, {"t": "p", "x": "Одоогийн шийд: x₁ = 25, s₂ = 30, Z = 1,250,000₮. Гэвч Z мөрөнд −15 (x₂ баганад) хэвээр байгаа тул оновчлолыг үргэлжлүүлнэ."}, {"t": "h", "lvl": 3, "x": "5.5.4. 2-р оновчлолын үе шат"}, {"t": "p", "x": "Орох багана: Z мөрөнд байгаа цорын ганц сөрөг тоо −15 (x₂ баганад) → x₂ орох багана болно."}, {"t": "p", "x": "Харьцааны тест:"}, {"t": "p", "x": "x₁ мөр: 25 / 0.5 = 50"}, {"t": "p", "x": "s₂ мөр: 30 / 3 = 10 (хамгийн бага)"}, {"t": "p", "x": "→ Гарах мөр: s₂. Ялгагч элемент: 3."}, {"t": "p", "x": "Гол мөрийг шинэчлэх (3-ыг 1 болгох): s₂ мөрийн бүх утгыг 3-т хуваана:"}, {"t": "p", "x": "[0, 3, −0.5, 1, 30] ÷ 3 = [0, 1, −0.1667, 0.3333, 10]"}, {"t": "p", "x": "x₁ мөрийг шинэчлэх (0.5-ыг 0 болгох): хуучин x₁ мөр − 0.5 × (шинэ x₂ мөр):"}, {"t": "p", "x": "[1, 0.5, 0.25, 0, 25] − 0.5·[0, 1, −0.1667, 0.3333, 10] = [1, 0, 0.3333, −0.1667, 20]"}, {"t": "p", "x": "Z мөрийг шинэчлэх (−15-ыг 0 болгох): хуучин Z мөр + 15 × (шинэ x₂ мөр):"}, {"t": "p", "x": "[0, −15, 12.5, 0, 1250] + 15·[0, 1, −0.1667, 0.3333, 10] = [0, 0, 10, 5, 1400]"}, {"t": "p", "x": "Шинэ хүснэгт:"}, {"t": "table", "rows": [["Суурь", "x₁", "x₂", "s₁", "s₂", "RHS"], ["x₁", "1", "0", "0.333", "−0.167", "20"], ["x₂", "0", "1", "−0.167", "0.333", "10"], ["Z", "0", "0", "10", "5", "1400"]]}, {"t": "h", "lvl": 3, "x": "5.5.5. Оновчтой шийдийг тайлах"}, {"t": "p", "x": "Z мөрөнд сөрөг тоо байхгүй болов (0, 0, 10, 5 — бүгд ≥ 0) → оновчтой шийд олдлоо."}, {"t": "p", "x": "Оновчтой шийд:"}, {"t": "p", "x": "x₁ = 20 ширээ"}, {"t": "p", "x": "x₂ = 10 сандал"}, {"t": "p", "x": "s₁ = 0 (мод бүрэн ашиглагдсан)"}, {"t": "p", "x": "s₂ = 0 (цаг бүрэн ашиглагдсан)"}, {"t": "p", "x": "Z = 1,400,000₮ ашиг"}, {"t": "p", "x": "Суурь баганад s₁, s₂ байхгүй байгааг анзаараарай — энэ нь 100 м³ мод, 80 цаг хоёулаа бүрэн, үлдэгдэлгүй ашиглагдсан гэсэн үг. Эдийн засагт үүнийг хүчинтэй хязгаарлалт (Binding Constraint) гэж нэрлэдэг: яг эдгээр хоёр нөөц үйлдвэрлэлийг хязгаарлаж буй гол хүчин зүйл юм."}, {"t": "h", "lvl": 3, "x": "5.5.6. Хариунуудын харьцуулалт"}, {"t": "p", "x": "Гурван өөр аргаар ижил бодлогыг бодоход:"}, {"t": "table", "rows": [["Арга", "x₁ (Ширээ)", "x₂ (Сандал)", "Z (ашиг)"], ["Бүлэг 3.5 — графикийн арга", "20", "10", "1,400,000₮ ✓"], ["Бүлэг 4.6 — матрицын арга", "20", "10", "1,400,000₮ ✓"], ["Бүлэг 5.5 — симплекс арга", "20", "10", "1,400,000₮ ✓"]]}, {"t": "p", "x": "Гурван ялгаатай аргаар (зурах, матрицын алгебр, алгоритмын давталт) яг ижил хариу гарч байгаа нь тохиолдлын зүйл биш. Энэ бол математикийн тохирлын баттай нотолгоо бөгөөд оройн цэгийн онол (Бүлэг 3.3) яагаад шугаман программчлалын онолын үндэс болдгийг харуулж байна."}, {"t": "h", "lvl": 2, "x": "5.6. Мэдрэмжийн шинжилгээ (Sensitivity Analysis)"}, {"t": "p", "x": "Онцгой чухал хэсэг. Мэдрэмжийн шинжилгээ бол симплекс аргын хамгийн үнэ цэнэтэй давуу тал бөгөөд менежментийн шийдвэр гаргахад хамгийн үр ашигтай хэрэглүүр юм."}, {"t": "h", "lvl": 3, "x": "5.6.1. Мэдрэмжийн шинжилгээ гэж юу вэ?"}, {"t": "p", "x": "Мэдрэмжийн шинжилгээ (Sensitivity Analysis) нь оновчтой шийд өгөгдлийн өөрчлөлтөд хэр мэдрэмтгий байгааг судалдаг: ямар өгөгдлийг (үнэ, нөөц) хэдэн хувиар өөрчилвөл шийд өөрчлөгдөх вэ гэдгийг тодорхойлно. Практикт үнэ ханш, нөөцийн хэмжээ байнга хэлбэлздэг тул мэдрэмжийн шинжилгээ нь тодорхой бус нөхцөлд итгэлтэй шийдвэр гаргах боломж олгодог."}, {"t": "p", "x": "Симплекс аргаар олсон “20 ба 10” гэсэн хариу бол зөвхөн өнөөдрийн зураг. Харин мэдрэмжийн шинжилгээ бол зах зээл дээр юу ч болсон таныг зөв зам дээр байлгах луужин юм."}, {"t": "h", "lvl": 3, "x": "5.6.2. Сүүдрийн үнэ (Shadow Price)"}, {"t": "p", "x": "Тодорхойлолт: сүүдрийн үнэ нь хязгаарлалтын сул гишүүн (b) 1 нэгжээр нэмэгдэхэд зорилгын функцийн утга хэдэн нэгжээр өөрчлөгдөхийг харуулна. Энэ утгыг эцсийн симплекс хүснэгтийн Z мөрөөс, тухайн нөөцийн нэмэлт хувьсагчийн (s₁, s₂) доорх тооноос шууд уншиж болно."}, {"t": "p", "x": "“Модон урлал”-ын эцсийн хүснэгтэд (5.5.4):"}, {"t": "p", "x": "s₁ баганад Z мөр = 10 → модны сүүдрийн үнэ"}, {"t": "p", "x": "s₂ баганад Z мөр = 5 → цагийн сүүдрийн үнэ"}, {"t": "p", "x": "Утга нь: 1 м³ мод нэмэгдвэл ашиг 10 нэгжээр (мянган төгрөгөөр), өөрөөр хэлбэл 10,000₮-өөр өснө. 1 цаг нэмэгдвэл ашиг 5 нэгжээр буюу 5,000₮-өөр өснө."}, {"t": "p", "x": "Практик хэрэглээ: модонд 1 м³-т 8,000₮ хүртэл нэмэгдэл төлбөр хийх нь ашигтай, учир нь 10,000₮ > 8,000₮ — цэвэр ашиг 2,000₮ нэмж олно. Мөн ажилчдын илүү цагийн хөлсийг шийдвэрлэхдээ 1 цагт 5,000₮-өөс дээш төлбөл алдагдалтай болохыг мэдэж болно."}, {"t": "p", "x": "Матрицын аргатай уялдаа: Бүлэг 4.5-т үзсэн урвуу матрицын элементүүд яг энэ сүүдрийн үнийг тооцоход ашиглагддаг — сүүдрийн үнэ = урвуу матрицын элемент × зорилгын коэффициент."}, {"t": "p", "x": "→ Хосмог бодлогод (Бүлэг 7): сүүдрийн үнэ = хосмог хувьсагчийн утга. Энэ бол Бүлэг 7-гийн гол сэдвүүдийн нэг."}, {"t": "h", "lvl": 3, "x": "5.6.3. Ашгийн зөвшөөрөгдөх муж (Range of Optimality)"}, {"t": "p", "x": "Тодорхойлолт: cⱼ (зорилгын коэффициент) ямар мужид өөрчлөгдөхөд одоогийн оновчтой суурь, өөрөөр хэлбэл x₁ = 20, x₂ = 10 гэсэн шийд хэвээр үлдэхийг харуулна."}, {"t": "table", "rows": [["Бүтээгдэхүүн", "Оновчтой тоо", "Нэгж ашиг (cⱼ)", "Зөвшөөрөгдөх өсөлт", "Зөвшөөрөгдөх бууралт", "Оновчтой муж"], ["Ширээ (x₁)", "20 ширхэг", "50,000₮", "+30,000₮", "−30,000₮", "[20,000 – 80,000]"], ["Сандал (x₂)", "10 ширхэг", "40,000₮", "+60,000₮", "−15,000₮", "[25,000 – 100,000]"]]}, {"t": "p", "x": "Тооцооллыг хэрхэн хийсэн бэ? x₁-ийн ашгийг Δ хэмжээгээр өөрчилнө гэж үзвэл эцсийн хүснэгтийн Z мөр дэх утгууд (10 ба 5) сөрөг болохгүй байх ёстой:"}, {"t": "p", "x": "10 + Δ·0.333 ≥ 0  →  Δ ≥ −30  (ашиг 50,000 − 30,000 = 20,000₮ хүртэл буурч болно)\n5 + Δ·(−0.167) ≥ 0  →  Δ ≤ 30  (ашиг 50,000 + 30,000 = 80,000₮ хүртэл өсч болно)"}, {"t": "p", "x": "Тайлбар: хэрэв зах зээл дээр ширээний ашиг 50,000₮-өөс 70,000₮ болж өсвөл бид үйлдвэрлэх тоогоо (20, 10) огт өөрчлөх шаардлагагүй — зөвхөн нийт ашиг маань өснө. Харин ашиг 80,000₮-өөс давбал шинээр симплекс бодолт хийж, зөвхөн ширээ хийх шинэ төлөвлөгөө рүү шилжих шаардлагатай болно."}, {"t": "p", "x": "Жишээ: модны үнэ өсөж, нэг ширээнээс олох ашиг 30,000₮ болж буурлаа гэж бодъё. Энэ нь зөвшөөрөгдөх доод хязгаар болох 20,000₮-өөс дээш, өөрөөр хэлбэл мужид багтаж байгаа тул компани хуучин төлөвлөгөөгөөрөө (20 ширээ, 10 сандал) ажилласаар байх нь хамгийн ашигтай хэвээр байна. Харин ашиг 15,000₮ болж, 20,000₮-ийн доод хязгаараас гарвал компани бодлогоо шинээр бодож, ширээний тоог багасгах шаардлагатай болно."}, {"t": "h", "lvl": 3, "x": "5.6.4. Нөөцийн зөвшөөрөгдөх муж (Range of Feasibility)"}, {"t": "p", "x": "Тодорхойлолт: bᵢ (нөөцийн хэмжээ) ямар мужид өөрчлөгдөхөд сүүдрийн үнэ хэвээр буюу тогтвортой үлдэхийг харуулна."}, {"t": "table", "rows": [["Нөөцийн төрөл", "Ашигласан", "Сүүдрийн үнэ", "Зөвшөөрөгдөх өсөлт", "Зөвшөөрөгдөх бууралт", "Хүчинтэй муж"], ["Мод (s₁)", "100 м³", "10,000₮", "+60 м³", "−60 м³", "[40 – 160]"], ["Цаг (s₂)", "80 цаг", "5,000₮", "+120 цаг", "−30 цаг", "[50 – 200]"]]}, {"t": "p", "x": "Тооцоолол: эцсийн хүснэгтийн s₁ багана дахь тоонууд 0.333 ба −0.167, RHS баганын утгууд 20 ба 10 байна."}, {"t": "p", "x": "Бууралтын хязгаар: эерэг коэффициенттой утгыг ашиглана: 20 / 0.333 = 60 → 100 − 60 = 40\nӨсөлтийн хязгаар: сөрөг коэффициенттой утгыг ашиглана: 10 / 0.167 = 60 → 100 + 60 = 160"}, {"t": "p", "x": "Эдийн засгийн утга: модны нөөц 100 м³-аас 160 м³ хүртэл нэмэгдэх хүртэл л мод бүрээс 10,000₮-ийн ашиг тогтвортой нэмж олно. Хэрэв мод үүнээс ч илүү ихэсвэл сандлын үйлдвэрлэл сөрөг утга руу орох гээд байгаа тул сүүдрийн үнэ (10,000₮) хүчингүй болно — энэ үед цаг гэсэн өөр нөөц гацаа (bottleneck) болж хувирна."}, {"t": "p", "x": "Практик хэрэглээ: нөөц нэмэх шийдвэр гаргах, хөрөнгө оруулалт төлөвлөхөд энэ мужийг мэдэх нь чухал — учир нь мужаас гадуур сүүдрийн үнэ өөрчлөгдөж, шинээр тооцоолол хийх шаардлагатай болно."}, {"t": "h", "lvl": 2, "x": "5.7. Кейс: 3 бүтээгдэхүүнтэй үйлдвэр"}, {"t": "p", "x": "Одоо симплекс аргын жинхэнэ хүчийг харуулах жишээ рүү орьё: гурван хувьсагчтай бодлого. Ийм бодлогыг графикийн аргаар (Бүлэг 3) шийдэхийн тулд гурван хэмжээст орон зайд зурах шаардлагатай болох тул хүн нүдээр харж бодох боломжгүй. Харин симплекс арга хувьсагчийн тооноос үл хамааран ижил алгоритмаар ажиллана."}, {"t": "h", "lvl": 3, "x": "5.7.1. Бизнесийн нөхцөл"}, {"t": "p", "x": "“Модон урлал” ХХК гурав дахь төрлийн бүтээгдэхүүн нэмж үйлдвэрлэхээр шийдлээ: ширээ (x₁), сандал (x₂), шүүгээ (x₃). Үйлдвэрт гурван төрлийн нөөц хязгаарлагдмал байна: мод (м³), цаг (ажиллах хугацаа), төмөр (кг, ширмэл иж бүрдэл эд ангид зориулсан). Компани нийт ашгаа хамгийн их байлгахыг зорьж байна."}, {"t": "h", "lvl": 3, "x": "5.7.2. Бодлогын тавилт"}, {"t": "p", "x": "Тооцооллыг гараар давтахад тохиромжтой байхаар жижиг тоотой, сургалтын зориулалттай жишээ өгөгдөл сонгов:"}, {"t": "p", "x": "max Z = 5x₁ + 4x₂ + 3x₃\n\n2x₁ + 3x₂ + x₃ ≤ 5   (мод, м³)\n4x₁ + x₂ + 2x₃ ≤ 11   (цаг)\n3x₁ + 4x₂ + 2x₃ ≤ 8   (төмөр, кг)\n\nx₁, x₂, x₃ ≥ 0"}, {"t": "h", "lvl": 3, "x": "5.7.3. Каноник хэлбэрт оруулах"}, {"t": "p", "x": "5.2-т үзсэн дүрмийн дагуу гурван нэмэлт хувьсагч (s₁, s₂, s₃) нэмнэ:"}, {"t": "p", "x": "max Z = 5x₁ + 4x₂ + 3x₃ + 0·s₁ + 0·s₂ + 0·s₃\n2x₁ + 3x₂ + x₃ + s₁ = 5\n4x₁ + x₂ + 2x₃ + s₂ = 11\n3x₁ + 4x₂ + 2x₃ + s₃ = 8\nx₁, x₂, x₃, s₁, s₂, s₃ ≥ 0"}, {"t": "p", "x": "s₁ = ашиглагдаагүй мод, s₂ = ашиглагдаагүй цаг, s₃ = ашиглагдаагүй төмөр — 5.2.3-т үзсэнтэй адил эдийн засгийн утгатай."}, {"t": "h", "lvl": 3, "x": "5.7.4. Анхны симплекс хүснэгт"}, {"t": "table", "rows": [["Суурь", "x₁", "x₂", "x₃", "s₁", "s₂", "s₃", "RHS"], ["s₁", "2", "3", "1", "1", "0", "0", "5"], ["s₂", "4", "1", "2", "0", "1", "0", "11"], ["s₃", "3", "4", "2", "0", "0", "1", "8"], ["Z", "−5", "−4", "−3", "0", "0", "0", "0"]]}, {"t": "h", "lvl": 3, "x": "5.7.5. Оновчлолын үе шатууд"}, {"t": "p", "x": "1-р үе шат. Z мөрийн хамгийн сөрөг тоо −5 (x₁ баганад) → x₁ орох багана. Харьцааны тест: 5 / 2 = 2.5,  11 / 4 = 2.75,  8 / 3 = 2.667. Хамгийн бага нь 2.5 → s₁ гарах мөр, ялгагч элемент = 2."}, {"t": "p", "x": "Гол мөрийг 2-т хуваана: [2, 3, 1, 1, 0, 0, 5] ÷ 2 = [1, 1.5, 0.5, 0.5, 0, 0, 2.5]. Бусад мөрийг үүгээр цэвэрлэвэл:"}, {"t": "table", "rows": [["Суурь", "x₁", "x₂", "x₃", "s₁", "s₂", "s₃", "RHS"], ["x₁", "1", "1.5", "0.5", "0.5", "0", "0", "2.5"], ["s₂", "0", "−5", "0", "−2", "1", "0", "1"], ["s₃", "0", "−0.5", "0.5", "−1.5", "0", "1", "0.5"], ["Z", "0", "3.5", "−0.5", "2.5", "0", "0", "12.5"]]}, {"t": "p", "x": "Одоогийн шийд: x₁ = 2.5, Z = 12.5. Гэвч Z мөрөнд −0.5 (x₃ баганад) байгаа тул үргэлжлүүлнэ."}, {"t": "p", "x": "2-р үе шат. Цорын ганц сөрөг тоо −0.5 (x₃ баганад) → x₃ орох багана. Харьцааны тест: x₁ мөр 2.5 / 0.5 = 5; s₂ мөрөнд x₃ баганын коэффициент 0 тул харьцаа тооцохгүй; s₃ мөр 0.5 / 0.5 = 1 (хамгийн бага) → s₃ гарах мөр, ялгагч элемент = 0.5."}, {"t": "p", "x": "Гол мөрийг 0.5-т хуваана: [0, −0.5, 0.5, −1.5, 0, 1, 0.5] ÷ 0.5 = [0, −1, 1, −3, 0, 2, 1]. Бусад мөрийг цэвэрлэвэл:"}, {"t": "table", "rows": [["Суурь", "x₁", "x₂", "x₃", "s₁", "s₂", "s₃", "RHS"], ["x₁", "1", "2", "0", "2", "0", "−1", "2"], ["s₂", "0", "−5", "0", "−2", "1", "0", "1"], ["x₃", "0", "−1", "1", "−3", "0", "2", "1"], ["Z", "0", "3", "0", "1", "0", "1", "13"]]}, {"t": "p", "x": "Z мөрөнд сөрөг тоо байхгүй (0, 3, 0, 1, 0, 1 — бүгд ≥ 0) → оновчтой шийд олдлоо. Ердөө хоёр үе шатанд бодлого шийдэгдлээ."}, {"t": "h", "lvl": 3, "x": "5.7.6. Оновчтой шийд"}, {"t": "p", "x": "x₁ = 2 ширхэг ширээ"}, {"t": "p", "x": "x₂ = 0 ширхэг сандал (энэ төлөвлөгөөнд үйлдвэрлэхгүй)"}, {"t": "p", "x": "x₃ = 1 ширхэг шүүгээ"}, {"t": "p", "x": "s₂ = 1 — цагийн нөөцөөс 1 нэгж ашиглагдалгүй үлдэнэ"}, {"t": "p", "x": "Z = 13 нэгж ашиг (жишээ өгөгдлийн масштабаар)"}, {"t": "p", "x": "Суурь баганад s₁ болон s₃ байхгүй байгааг анзаараарай — энэ нь мод, төмөр хоёулаа бүрэн ашиглагдсан (Binding Constraint) гэсэн үг. Харин s₂ = 1 суурьт байгаа нь цагийн нөөц бүрэн шавхагдаагүй, өөрөөр хэлбэл цаг энэ жишээнд хязгаарлагч хүчин зүйл биш болохыг харуулж байна."}, {"t": "h", "lvl": 3, "x": "5.7.7. Эдийн засгийн тайлбар"}, {"t": "p", "x": "Эцсийн Z мөрөнд s₁ баганад 1, s₃ баганад 1 гэсэн тоо байгаа нь эдгээр хоёр нөөцийн сүүдрийн үнэ юм: мод 1 нэгжээр нэмэгдвэл ашиг 1 нэгжээр, төмөр 1 нэгжээр нэмэгдвэл мөн адил ашиг 1 нэгжээр өснө. Харин s₂ (цаг) баганад Z мөрөнд 0 байна — учир нь s₂ өөрөө суурь хувьсагч буюу илүүдэлтэй нөөц болсон тул нэмэлт цаг өгсөн ч ашигт нэмэр өгөхгүй."}, {"t": "p", "x": "Энэ бол хосмог онолын гүйцээх сул шинж (Complementary Slackness) гэдэг чухал зарчмын анхны жишээ юм: хэрэв нөөц бүрэн ашиглагдаагүй бол (s > 0) түүний сүүдрийн үнэ 0 байх ёстой; харин нөөц бүрэн ашиглагдсан үед (s = 0) л сүүдрийн үнэ эерэг байж болно."}, {"t": "p", "x": "→ Энэ зарчмыг Бүлэг 7-д “Гүйцээх сул шинж (Complementary Slackness)” нэрээр бүрэн, албан ёсны байдлаар үзнэ."}, {"t": "h", "lvl": 2, "x": "5.8. Симплекс аргын хязгаарлал"}, {"t": "h", "lvl": 3, "x": "5.8.1. Хэзээ ажиллах вэ?"}, {"t": "p", "x": "Бүх хязгаарлалт ≤ тэмдэгтэй, max зорилготой бодлогод."}, {"t": "p", "x": "Каноник хэлбэрт шууд оруулах боломжтой бодлогод — өөрөөр хэлбэл эхний суурь боломжит шийд (s₁ = b₁, s₂ = b₂, …) байгалиасаа боломжит (feasible) байх ёстой."}, {"t": "h", "lvl": 3, "x": "5.8.2. Хэзээ ажиллахгүй вэ?"}, {"t": "p", "x": "Стандарт симплекс арга дараах тохиолдолд шууд ажиллахгүй:"}, {"t": "p", "x": "Хязгаарлалт ≥ эсвэл = тэмдэгтэй үед — учир нь ийм үед “бүх x = 0” гэсэн гарааны цэг боломжит шийд болдоггүй (жишээ нь x ≥ 10 хязгаарлалтыг x = 0 хангахгүй)."}, {"t": "p", "x": "Min бодлогод — гэвч үүнийг 5.2.5-т үзсэнчлэн max болгож хувиргах боломжтой тул энэ өөрөө том асуудал биш."}, {"t": "p", "x": "→ ≥ болон = хязгаарлалттай бодлогыг Big-M арга (Big-M Method) ашиглан шийднэ — Бүлэг 6-гийн гол сэдэв."}, {"t": "h", "lvl": 3, "x": "5.8.3. Тусгай тохиолдлууд"}, {"t": "p", "x": "Гажуудал (Degeneracy): харьцааны тестэд хоёр ба түүнээс дээш мөр тэнцүү хамгийн бага харьцаа өгөх үед үүснэ. Ийм үед алгоритм нэг цэг дээр удаан “гацаж”, үе шат хийсэн ч Z утга сайжрахгүй байх боломжтой."}, {"t": "p", "x": "Олон оновчтой шийд (Multiple Optimal Solutions): эцсийн хүснэгтийн Z мөрөнд суурийн бус хувьсагчийн доор 0 үлдсэн тохиолдолд өөр оройн цэг дээр ч ижил оновчтой Z утга авах боломжтой болно."}, {"t": "p", "x": "Хязгааргүй шийд (Unbounded Solution): орох баганад бүх коэффициент сөрөг буюу тэг байвал (эерэг тоо байхгүй бол) харьцааны тест хийх боломжгүй болж, гарах мөр олдохгүй. Энэ нь зорилгын функц хязгааргүй өсөх боломжтой гэсэн үг бөгөөд практикт ихэвчлэн бодлогын тавилтад алдаа гарсныг илтгэдэг."}, {"t": "h", "lvl": 2, "x": "Бүлгийн хураангуй"}, {"t": "p", "x": "Симплекс арга нь Ж.Б. Данцигийн 1947 онд бүтээсэн, гурав ба түүнээс дээш хувьсагчтай шугаман программчлалын бодлогыг шийдвэрлэх алгоритм юм."}, {"t": "p", "x": "Симплекс аргаар бодохын өмнө бодлогыг каноник хэлбэрт оруулж, ≤ хязгаарлалт бүрт нэмэлт хувьсагч (Slack) нэмнэ."}, {"t": "p", "x": "Симплекс хүснэгт нь бодлогын бүх мэдээллийг хураангуйлан харуулах бөгөөд Z мөрөнд байрлах сөрөг коэффициентүүд нь ашиг олох боломжийг илэрхийлдэг."}, {"t": "p", "x": "Оновчлолын үе шат (Iteration) бүрд орох багана (хамгийн сөрөг Z), гарах мөр (хамгийн бага харьцаа)-ыг сонгож, ялгагч элементээр дамжуулан хүснэгтийг шинэчилнэ."}, {"t": "p", "x": "“Модон урлал” ХХК-ийн бодлогыг симплекс аргаар бодоход x₁ = 20, x₂ = 10, Z = 1,400,000₮ гарч, Бүлэг 3 (график), Бүлэг 4 (матриц)-ын хариутай яг ижил байв."}, {"t": "p", "x": "Мэдрэмжийн шинжилгээ нь эцсийн хүснэгтээс сүүдрийн үнэ, ашгийн зөвшөөрөгдөх муж, нөөцийн зөвшөөрөгдөх мужийг гаргаж, менежментийн шийдвэрт ашиглах боломж олгодог."}, {"t": "p", "x": "Симплекс арга зөвхөн ≤ хязгаарлалттай max бодлогод шууд ажиллана; ≥ болон = хязгаарлалттай бодлогыг Big-M аргаар (Бүлэг 6) шийднэ."}, {"t": "h", "lvl": 2, "x": "Дасгал ажил (10 дасгал)"}, {"t": "h", "lvl": 3, "x": "Хялбар (3 дасгал)"}, {"t": "p", "x": "Дасгал 1. Дараах бодлогыг каноник хэлбэрт оруул. Нэмэлт хувьсагчийн эдийн засгийн утгыг тайлбарла."}, {"t": "p", "x": "max Z = 6x₁ + 8x₂\n5x₁ + 10x₂ ≤ 60\n4x₁ + 4x₂ ≤ 40\nx₁, x₂ ≥ 0"}, {"t": "p", "x": "Дасгал 2. Дасгал 1-ийн бодлогод анхны симплекс хүснэгтийг байгуул. Орох багана болон гарах мөрийг тодорхойл (харьцааны тестийг тооцоолж харуул)."}, {"t": "p", "x": "Дасгал 3. Дасгал 2-т сонгосон ялгагч элементийн үүргийг тайлбарла: яагаад тэр элементийг 1 болгодог вэ, бусад мөрийг яагаад 0 болгодог вэ? Нэг оновчлолын үе шатны тооцооллыг бүрэн хийж, шинэ хүснэгтийг гарга."}, {"t": "h", "lvl": 3, "x": "Дунд зэрэг (4 дасгал)"}, {"t": "p", "x": "Дасгал 4. Хоёр хувьсагчтай, гурван хязгаарлалттай дараах бодлогыг симплекс аргаар бүрэн бод. Хариугаа графикийн аргаар (Бүлэг 3-ын аргаар) шалгаж, харьцуул."}, {"t": "p", "x": "max Z = 3x₁ + 2x₂\nx₁ + x₂ ≤ 4\nx₁ + 3x₂ ≤ 6\nx₁ ≤ 3\nx₁, x₂ ≥ 0"}, {"t": "p", "x": "Дасгал 5. “Модон урлал” ХХК гурав дахь агуулах нэмж, тавилгын үйлдвэрлэлээ гурван бүтээгдэхүүн (x₁, x₂, x₃) болгон өргөтгөв. Дараах бодлогыг симплекс аргаар бод."}, {"t": "p", "x": "max Z = 40x₁ + 30x₂ + 20x₃\n2x₁ + x₂ + x₃ ≤ 100\nx₁ + 2x₂ + x₃ ≤ 80\nx₁, x₂, x₃ ≥ 0"}, {"t": "p", "x": "Дасгал 6. Дасгал 4-т олсон оновчтой шийдэд мэдрэмжийн шинжилгээ хий: (а) x₁-ийн ашгийн зөвшөөрөгдөх мужийг ол; (б) хоёр хязгаарлалтын сүүдрийн үнийг тодорхойлж, эдийн засгийн утгыг тайлбарла."}, {"t": "p", "x": "Дасгал 7. ХААИС-ийн туршилтын талбайд гурван төрлийн ургамал (улаанбуудай x₁, овъёос x₂, арвай x₃) тарихаар төлөвлөж байна. Газар (га), ус (м³), хөдөлмөр (хүн/өдөр) хязгаарлагдмал. Дараах бодлогыг симплекс аргаар бодож, дараа нь мэдрэмжийн шинжилгээ хий."}, {"t": "p", "x": "max Z = 8x₁ + 10x₂ + 6x₃  (ашиг, сая ₮/га)\nx₁ + x₂ + x₃ ≤ 100   (газар, га)\n3x₁ + 2x₂ + x₃ ≤ 240   (ус, мянган м³)\n2x₁ + 4x₂ + x₃ ≤ 150   (хөдөлмөр, хүн/өдөр)\nx₁, x₂, x₃ ≥ 0"}, {"t": "h", "lvl": 3, "x": "Төвөгтэй (3 дасгал)"}, {"t": "p", "x": "Дасгал 8. Хөрөнгө оруулалтын компани дөрвөн төрлийн хөрөнгөд (x₁, x₂, x₃, x₄) нийт хөрөнгөө хуваарилах гэж байна. Нийт хөрөнгийн болон хоёр төрлийн эрсдэлийн хязгаарлалттай. Симплекс аргаар оновчтой хуваарилалтыг ол."}, {"t": "p", "x": "max Z = 7x₁ + 9x₂ + 5x₃ + 6x₄  (хүлээгдэж буй өгөөж, хувиар)\nx₁ + x₂ + x₃ + x₄ ≤ 100   (нийт хөрөнгө)\nx₁ + 2x₂ + x₄ ≤ 120   (эрсдэлийн хязгаарлалт 1)\nx₂ + 2x₃ + x₄ ≤ 90   (эрсдэлийн хязгаарлалт 2)\nx₁, x₂, x₃, x₄ ≥ 0"}, {"t": "p", "x": "Дасгал 9. Дасгал 7-гийн мэдрэмжийн шинжилгээний үр дүнг ашиглан “Хэрэв бид нэмж 10 га газар түрээслэж чадвал энэ шийдвэр ашигтай юу?” гэсэн менежментийн асуултад сүүдрийн үнэд үндэслэн хариул."}, {"t": "p", "x": "Дасгал 10. Дараах бодлогыг симплекс аргаар бод. Эцсийн хүснэгтийг сайтар шинжилж, энэ бодлого яагаад олон оновчтой шийдтэй болохыг тайлбарла (зорилгын функцийн коэффициент болон хязгаарлалтын коэффициентийн харьцааг харьцуулж үзээрэй)."}, {"t": "p", "x": "max Z = 4x₁ + 6x₂\n2x₁ + 3x₂ ≤ 12\nx₁, x₂ ≥ 0"}, {"t": "h", "lvl": 2, "x": "Хариу түлхүүр (сонгосон дасгалууд)"}, {"t": "p", "x": "Дасгал 1: 5x₁ + 10x₂ + s₁ = 60, 4x₁ + 4x₂ + s₂ = 40 (s₁, s₂ ≥ 0). s₁, s₂ нь тус бүрдээ эхний болон хоёр дахь нөөцийн ашиглагдаагүй үлдэгдлийг илэрхийлнэ."}, {"t": "p", "x": "Дасгал 2: орох багана — x₂ (Z мөрөнд −8, хамгийн сөрөг нь). Харьцаа: 60 / 10 = 6, 40 / 4 = 10 → гарах мөр нь s₁ мөр (харьцаа 6 хамгийн бага). Ялгагч элемент = 10."}, {"t": "p", "x": "Дасгал 3: гол мөрийг 10-т хуваасны дараах шинэ хүснэгтэд x₂ = 6, s₂ = 16, Z = 48 болно. (Оновчлол хараахан дуусаагүй; Z мөрөнд сөрөг тоо үлдсэн эсэхийг өөрөө шалгаарай.)"}, {"t": "p", "x": "Дасгал 4: оновчтой шийд — x₁ = 3, x₂ = 1, Z = 11. Графикийн аргаар шалгахад мөн адил (3, 1) оройн цэг дээр гарна."}, {"t": "p", "x": "Дасгал 5: оновчтой шийд — x₁ = 40, x₂ = 20, x₃ = 0, Z = 2,200."}, {"t": "p", "x": "Дасгал 6: Дасгал 4-ийн эцсийн хүснэгтээс x₁-ийн ашгийн зөвшөөрөгдөх муж болон хоёр хязгаарлалтын сүүдрийн үнийг тухайн хүснэгтийн s багануудаас унших ёстой — оюутан өөрийн бодсон эцсийн хүснэгтээ ашиглан тооцоолно."}, {"t": "p", "x": "Дасгал 7: оновчтой шийд — x₁ = 50, x₂ = 0, x₃ = 50, Z = 700 (сая ₮)."}, {"t": "p", "x": "Дасгал 8: оновчтой шийд — x₁ = 80, x₂ = 20, x₃ = 0, x₄ = 0, Z = 740."}, {"t": "p", "x": "Дасгал 9: Дасгал 7-гийн эцсийн хүснэгтээс газрын сүүдрийн үнийг уншиж, 10 га нэмэхэд нийт ашиг хэдээр өсөхийг тооцоол (сүүдрийн үнэ × 10). Хэрэв түрээсийн зардал энэ өсөлтөөс бага бол шийдвэр ашигтай."}, {"t": "p", "x": "Дасгал 10: оновчтой утга Z = 24 боловч (x₁ = 6, x₂ = 0) ба (x₁ = 0, x₂ = 4) хоёулаа Z = 24 өгнө — учир нь зорилгын функцийн коэффициентийн харьцаа (4 : 6) хязгаарлалтын коэффициентийн харьцаатай (2 : 3) яг тэнцүү тул зорилгын шугам хязгаарлалтын шугамтай параллель байна. Иймд (6, 0)-оос (0, 4) хүртэлх хэрчмийн бүх цэг оновчтой шийд болно — олон оновчтой шийдийн сонгодог жишээ."}]};
